// One line per page. mustContain is optional: a word or phrase that only appears when the page renders correctly
// (a footer line, your phone number, a product name). It catches blank pages and error pages that still return 200.
const timeoutSeconds = 10; // slower than this counts as down

const pages = [
  { url: 'https://www.example.com/', mustContain: 'Example' },
  { url: 'https://www.example.com/pricing', mustContain: '' },
  { url: 'https://www.example.com/contact', mustContain: '' },
];

return pages.map((p) => ({ json: { ...p, timeoutSeconds } }));

// Alert rules
const failuresBeforeAlert = 2; // consecutive failed checks before the first alert (2 = about 15 min at this schedule)
const remindEveryHours = 4;    // reminder while still down; 0 turns reminders off

// Workflow static data survives between runs of an ACTIVE workflow. Manual test runs do not save it.
const state = $getWorkflowStaticData('global');
state.pages = state.pages || {};
const now = Date.now();
const minutes = (ms) => {
  const m = Math.round(ms / 60000);
  return m < 60 ? m + ' min' : Math.floor(m / 60) + ' h ' + (m % 60) + ' min';
};

const alerts = [];
$input.all().forEach((item, i) => {
  const page = $('Pages to check').itemMatching(i).json;
  const res = item.json;
  const body = String(res.data ?? res.body ?? '');

  let problem = '';
  if (res.error) {
    const msg = String(res.error.message || res.error.description || res.error);
    problem = /timeout|timed out|ECONNABORTED|ETIMEDOUT/i.test(msg)
      ? 'no response within ' + page.timeoutSeconds + 's'
      : 'request failed: ' + msg.slice(0, 120);
  } else if (!(res.statusCode >= 200 && res.statusCode < 300)) {
    problem = 'HTTP ' + res.statusCode + (res.statusMessage ? ' ' + res.statusMessage : '');
  } else if (page.mustContain && !body.includes(page.mustContain)) {
    problem = 'page loads but the text "' + page.mustContain + '" is missing';
  }

  const s = state.pages[page.url] || { failures: 0, down: false, since: 0, lastAlert: 0 };
  if (problem) {
    s.failures += 1;
    if (!s.since) s.since = now;
    if (!s.down && s.failures >= failuresBeforeAlert) {
      s.down = true;
      s.lastAlert = now;
      alerts.push(':red_circle: *DOWN* ' + page.url + '\n' + problem);
    } else if (s.down && remindEveryHours > 0 && now - s.lastAlert >= remindEveryHours * 3600000) {
      s.lastAlert = now;
      alerts.push(':red_circle: *Still down* after ' + minutes(now - s.since) + ': ' + page.url + '\n' + problem);
    }
    state.pages[page.url] = s;
  } else {
    if (s.down) alerts.push(':large_green_circle: *Back up* ' + page.url + '\nDown for about ' + minutes(now - s.since));
    state.pages[page.url] = { failures: 0, down: false, since: 0, lastAlert: 0 };
  }
});

// No alerts means no output items, so Slack is not called.
return alerts.map((text) => ({ json: { text } }));
